create function public.cineo_show_metadata(ids bigint[]) returns jsonb language sql stable security invoker set search_path='' as $$
select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'duration_seconds',coalesce((select sum(duration_seconds) from public.cineo_episodes e where e.show_id=s.id and e.review_status='approved' and not e.hidden),0),'episode_count',(select count(*) from public.cineo_episodes e where e.show_id=s.id and e.review_status='approved' and not e.hidden),'creator_name',coalesce((select name from public.cineo_profiles p where p.user_id=s.owner_id),'Criador independente'),'rating_average',coalesce((select round(avg(stars),1) from public.cineo_ratings r where r.show_id=s.id),0),'rating_count',(select count(*) from public.cineo_ratings r where r.show_id=s.id))),'[]'::jsonb) from public.cineo_shows s where s.id=any(ids);$$;
revoke all on function public.cineo_show_metadata(bigint[]) from public,anon,authenticated;
grant execute on function public.cineo_show_metadata(bigint[]) to service_role;
